"""Generate a local bilingual documentation gallery from real CLI responses."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
TAG = 'v0.1.0-alpha.1'
OUT = ROOT / 'docs/demo'
EVIDENCE = ROOT / 'docs/validation/evidence' / ('release-' + TAG + '-r2')
OUT.mkdir(parents=True, exist_ok=True)
commands = json.loads((EVIDENCE / 'commands.json').read_bytes())
for row in commands:
    row['response'] = json.loads((EVIDENCE / row['stdout']).read_bytes())
data = {'release': TAG, 'commands': commands,
        'receipt': json.loads((EVIDENCE / 'verification.json').read_bytes())}
(OUT / 'case-data.json').write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf8')

